logger = BackgroundLogger.Instance()


class CallUtils(object):
    """
    Class for calls related operations
    """
    store = Store()

    def __init__(self):
        self.parameter_obj = Parameters()
        self.config = ConfigHandler.get_config()
        self.exc_info = None
        self.ip_exception_flag = 0
        self.teid_exception_flag = 0
        self.exception_flag = 0
        self.admin_alias = None
        self.iperf_device = 'device1'

    def call_setup(self, **kwargs):
        """
          Attaches UE
        :param kwargs: dut: default is 'bts'
        :param kwargs: lte: value is deviceid:data:analsis1:analysis2:.. or
                            deviceid:voice:analysis1:analysis2:..
        :param kwargs: wcdma: value is deviceid:data:analysis1:analysis2:.. or
                            deviceid:voice:analysis1:analysis2:..
        :param kwargs: gsm: value is deviceid:data:analysis1:analysis2:.. or
                            deviceid:voice:analysis1:analysis2:..
        :param kwargs: parallel: True or False to attach in parallel or not
        :param kwargs: capture_device: The device where messages should be captured for
                            attach verification
        :param kwargs: traffic_filters_file : Default is traffic_filters.json
        :return:
        """
        self.admin_alias = kwargs.get('admin_alias', None)
        is_parallel = kwargs.pop('parallel', False)
        self.iperf_device = kwargs.pop("iperf_device", "device1")
        verify_attach = kwargs.pop('verify_attach', True)
        capture_device = kwargs.pop('capture_device', 'calls_capture_device')
        traffic_filters_json = kwargs.pop('traffic_filters_file', 'traffic_filters.json')
        verify_teid = kwargs.pop('verify_teid', False)
        dut = kwargs.pop('dut', 'bts')
        ip_v4_or_6 = kwargs.pop('ipv4_or_6', 'ipv4')
        variables_to_replace = kwargs.pop('variables', '')
        self.ue_ip_dict = {}
        #
        # if is_parallel is True:
        #     logger.info('Running in parallel')
        #     return self._run_call_setup_in_parallel(**kwargs)

        if is_parallel is True:
            all_given_ue_types = self._get_all_given_ue_types(kwargs)
            unique_ue_types = list(set(all_given_ue_types))
            if len(unique_ue_types) == 1 and unique_ue_types[0] == 'module':
                self._run_call_setup_sequentially(verify_attach, capture_device,
                                                  traffic_filters_json, verify_teid, dut,
                                                  ip_v4_or_6, variables_to_replace, **kwargs)
            else:
                self._run_call_setup_in_parallel(verify_attach, capture_device,
                                                 traffic_filters_json, verify_teid, dut,
                                                 ip_v4_or_6, variables_to_replace, **kwargs)
        else:
            self._run_call_setup_sequentially(verify_attach, capture_device,
                                              traffic_filters_json, verify_teid, dut,
                                              ip_v4_or_6, variables_to_replace, **kwargs)
        logger.debug('\t' + '#' * 60 + ' \n\t\tUE IP dictionary : {}\n'.format(self.ue_ip_dict))
        logger.debug('\t' + '#' * 60)
        return self.ue_ip_dict

    def _get_all_given_ue_types(self, kwargs):
        all_ue_types = []
        for rat, val in list(kwargs.items()):
            device_id, call_type, analysis_list = self._unpack_rat_user_argument(val)
            ue_type = get_config_variable(['ue_devices', rat, device_id, "ue_type"])
            all_ue_types.append(ue_type)
        logger.debug('All UE Types {}'.format(all_ue_types))
        return all_ue_types

    def call_start(self, **kwargs):
        """
            Starts calls for the attached UE
        :param kwargs: lte: value is deviceid:data or deviceid:voice
        :param kwargs: wcdma: value is deviceid:data or deviceid:voice
        :param kwargs: gsm: value is deviceid:data or deviceid:voice
        :param kwargs: profile: which data profile to be used from the Config
        :return: None
        """
        profile = kwargs.pop('profile', None)
        self.iperf_device = kwargs.pop('iperf_device', "device1")
        for key, value, in list(kwargs.items()):
            if key in get_config_variable(['rat_env']):
                device_id, call_type = value.split(':')
                alias = self._get_alias(key, device_id, call_type)
                ue_obj = CallUtils.store.get(alias=alias)
                ue_obj.call_start(call_type, self.iperf_device, profile, **kwargs)
            else:
                logger.debug('Ignoring RAT {}'.format(key))

    def call_stop(self, **kwargs):
        """
            Stops calls for the specified UE
        :param kwargs: lte: value is deviceid:data or deviceid:voice
        :param kwargs: wcdma: value is deviceid:data or deviceid:voice
        :param kwargs: gsm: value is deviceid:data or deviceid:voice
        :param kwargs: profile: the profile needs to be started
        :return: Throughput for data call
        """
        for key, value, in list(kwargs.items()):
            if key in get_config_variable(['rat_env']):
                device_id, call_type = value.split(':')
                alias = self._get_alias(key, device_id, call_type)
                ue_obj = CallUtils.store.get(alias=alias)
                profile = kwargs['profile'] if 'profile' in list(kwargs.keys()) else None
                return ue_obj.call_stop(call_type, profile)
            else:
                logger.debug('Ignoring RAT {}'.format(key))

    def call_teardown(self, **kwargs):
        """
            Tears down. Detaches all the UEs attached in Call Setup
        :param kwargs: lte: value is deviceid:data or deviceid:voice
        :param kwargs: wcdma: value is deviceid:data or deviceid:voice
        :param kwargs: gsm: value is deviceid:data or deviceid:voice
        """
        for key, value, in list(kwargs.items()):
            if key in get_config_variable(['rat_env']):
                device_id, call_type = value.split(':')
                alias = self._get_alias(key, device_id, call_type)
                if CallUtils.store.has_alias(alias):
                    ue_obj = CallUtils.store.get(alias=alias)
                    try:
                        ue_obj.detach()
                    except Exception as e:
                        logger.warn("Exception from call_teardown during detach :: {}".format(e))
                    # ue_obj.call_stop(call_type='voice')  # TBD: Stop data too here.
                    # Need to find all the profiles before that
                    # ue_obj.call_teardown()
                    CallUtils.store.remove(alias=alias)

    def ue_statistics(self, **kwargs):
        """ue statistics"""
        ue_object = CallUtils.store.get(alias=kwargs.get('alias'))
        return ue_object.ue_statistics()

    def call_detach(self, **kwargs):
        """
            Detaches all the UEs provided as arguments
        :param kwargs: lte: value is deviceid
        :param kwargs: wcdma: value is deviceid
        :param kwargs: gsm: value is deviceid
        """
        ip_v4_or_6 = kwargs.pop('ipv4_or_6', 'ipv4')
        for rat, devid_calltype, in list(kwargs.items()):
            if rat in get_config_variable(['rat_env']):
                device_id, call_type = devid_calltype.split(':')
                alias = self._get_alias(rat, device_id, devid_calltype)
                ue_obj = self._get_ue_obj_from_store(alias)
                if ue_obj is None:
                    ue_obj = self._create_ue_object(rat, device_id, ip_v4_or_6=ip_v4_or_6)
                ue_obj.detach()
            else:
                logger.info('RAT {} ignored'.format(rat))

    def _run_call_setup_in_parallel(self, verify_attach, capture_device, traffic_filters_json,
                                    verify_teid, dut, ip_v4_or_6,
                                    variables_to_replace, **kwargs):
        """
        Performs the following operations
         1. Initiates attach on multiple UEs simultaneously
         2. Verifies the attach messages optionally
        Args:
            **kwargs:
                iperf_device: Optional (default - device1) : The iperf device name according to
                        testline_config, the iperf remote ip is used to create route incase of
                        dongle attach
                verify_attach: Optional (default - True): If True verifies the attach messages
                        captured at the given capture device
                capture_device: Optional (default - calls_capture_device): The device where the
                        traffic capture has to happen. If verify_attach is true, this argument
                        is considered.
                traffic_filters_file: Optional (default - lte: 'lte_attach_request',
                                                    'lte_attach_accept', 'lte_attach_complete'
                                                default - wcdma: 'wcdma_attach_request',
                                                    'wcdma_attach_response'
                                                default - gsm: 'gsm_call_proceeding',
                                                '   gsm_connect_ack')
                                      The resource file where the filters will be picked from.
                verify_teid: Optional ( default - False): If True verifies if TEID is generated
                    after attach on the given dut
                dut: Optional ( default - bts): The device where the TEID verification has to
                    happen.
        Returns: Dictionary of all the UE IPs
        """
        logger.info("Parallel call")
        threads_dict = {}
        for rat, value, in list(kwargs.items()):
            if rat in get_config_variable(['rat_env']):
                device_id, call_type, analysis_list = self._unpack_rat_user_argument(value)
                alias, ue_obj = self._check_if_device_in_use(rat, device_id, call_type)
                if ue_obj is None:
                    ue_obj = self._create_ue_object(rat, device_id, dut, ip_v4_or_6)
                if verify_attach:
                    admin_alias = _setup_oam_ops(alias=self.admin_alias)
                    _generate_scf(alias=admin_alias)
                threads_dict[alias] = Thread(target=self._attach_and_capture,
                                             args=(ue_obj, dut, rat, device_id, call_type,
                                                   verify_attach, capture_device, analysis_list,
                                                   traffic_filters_json, alias, verify_teid,
                                                   ip_v4_or_6, variables_to_replace), name=alias)
                threads_dict[alias].start()
                time.sleep(2)
            else:
                logger.info('RAT {} ignored'.format(rat))
        for alias, thread_obj in list(threads_dict.items()):
            thread_obj.join()
            logger.debug('Joined thread: {}'.format(alias))
        logger.log_background_messages()

        if self.ip_exception_flag:
            raise IpNotFoundException
        if self.teid_exception_flag:
            raise TEIDNotGeneratedException
        if self.exception_flag:
            raise Exception("Failed in Call attach")

    def _run_call_setup_sequentially(self, verify_attach, capture_device, traffic_filters_json,
                                     verify_teid, dut, ip_v4_or_6, variables_to_replace,
                                     **kwargs):
        """
        Performs the following operations
         1. Initiates attach for the given UE
         2. Verifies the attach messages optionally
        Args:
            **kwargs:
                iperf_device: Optional (default - device1) : The iperf device name according to
                        testline_config, the iperf remote ip is used to create route incase of
                        dongle attach
                verify_attach: Optional (default - True): If True verifies the attach messages
                        captured at the given capture device
                capture_device: Optional (default - calls_capture_device): The device where the
                        traffic capture has to happen. If verify_attach is true, this argument
                        is considered.
                traffic_filters_file: Optional (default - lte: 'lte_attach_request',
                                                    'lte_attach_accept', 'lte_attach_complete'
                                                default - wcdma: 'wcdma_attach_request',
                                                    'wcdma_attach_response'
                                                default - gsm: 'gsm_call_proceeding',
                                                    'gsm_connect_ack')
                                      The resource file where the filters will be picked from.
                verify_teid: Optional ( default - False): If True verifies if TEID is generated
                    after attach on the given dut
                dut: Optional ( default - bts): The device where the TEID verification has to
                    happen.
        Returns: Dictionary of all the UE IPs
        """
        logger.info("Sequential call")
        for rat, value, in list(kwargs.items()):
            if rat in get_config_variable(['rat_env']):
                device_id, call_type, analysis_list = self._unpack_rat_user_argument(value)
                ue_alias, ue_obj = self._check_if_device_in_use(rat, device_id, call_type)
                if ue_obj is None:
                    ue_obj = self._create_ue_object(rat, device_id, dut, ip_v4_or_6, **kwargs)
                self._attach_and_capture(ue_obj, dut, rat, device_id, call_type, verify_attach,
                                         capture_device, analysis_list, traffic_filters_json,
                                         ue_alias, verify_teid, ip_v4_or_6, variables_to_replace)
            else:
                logger.info('RAT {} ignored'.format(rat))

    def _unpack_rat_user_argument(self, value):
        arg_values = value.split(':')
        analysis_list = None
        if len(arg_values) > 2:
            device_id, call_type = arg_values[0], arg_values[1]
            analysis_list = arg_values[2:]
        else:
            device_id, call_type = arg_values
        return device_id, call_type, analysis_list

    def _check_if_device_in_use(self, rat, device_id, call_type):
        alias = self._get_alias(rat, device_id, call_type)
        all_aliases = CallUtils.store.aliases
        for in_use_alias in all_aliases:
            in_use_rat, in_use_device_id, in_use_call_type = in_use_alias.split(':', 2)
            in_use_ue_type = get_config_variable(['ue_devices', in_use_rat, in_use_device_id,
                                                  "ue_type"])
            ue_type = get_config_variable(['ue_devices', rat, device_id, "ue_type"])
            if ue_type.lower() == 'mobile' and in_use_ue_type.lower() == 'mobile':
                in_use_device_unque_id = get_config_variable(['ue_devices', in_use_rat,
                                                              in_use_device_id, 'adb_id'])
                current_alias_device_unque_id = get_config_variable(['ue_devices', rat,
                                                                     device_id, 'adb_id'])
                self._check_if_device_id_in_use(device_id, current_alias_device_unque_id,
                                                in_use_device_id, in_use_device_unque_id, alias)
            elif ue_type.lower() == 'dongle' and in_use_ue_type.lower() == 'dongle':
                in_use_device_unque_id = get_config_variable(['ue_devices', in_use_rat,
                                                              in_use_device_id, 'dongle_id'])
                current_alias_device_unque_id = get_config_variable(['ue_devices', rat,
                                                                     device_id, 'dongle_id'])
                self._check_if_device_id_in_use(device_id, current_alias_device_unque_id,
                                                in_use_device_id, in_use_device_unque_id, alias)
            elif ue_type.lower() == 'module' and in_use_ue_type.lower() == 'module':
                in_use_device_unque_id = get_config_variable(['ue_devices', in_use_rat,
                                                              in_use_device_id, 'imei'])
                current_alias_device_unque_id = get_config_variable(['ue_devices', rat,
                                                                     device_id, 'imei'])
                self._check_if_device_id_in_use(device_id, current_alias_device_unque_id,
                                                in_use_device_id, in_use_device_unque_id, alias)
        return alias, self._get_ue_obj_from_store(alias)

    def _get_ue_obj_from_store(self, alias):
        if CallUtils.store.has_alias(alias):
            return CallUtils.store.get(alias)

    def _check_if_device_id_in_use(self, device_id, current_alias_device_unque_id,
                                   in_use_device_id, in_use_device_unque_id, alias):
        if current_alias_device_unque_id == in_use_device_unque_id:
            logger.debug('{} with id {} already in use. Please check testline config {} '
                         'with id {} for duplicacy.'.format(in_use_device_id,
                                                            in_use_device_unque_id, device_id,
                                                            current_alias_device_unque_id))
            raise DeviceInUseException(alias)

    def _attach_and_capture(self, ue_obj, dut, rat, device_id, call_type, verify_attach,
                            capture_device, analysis_list, traffic_filters_json, ue_alias,
                            verify_teid, ip_v4_or_6, variables):
        if ue_obj.ue_type == "iphy" or ue_obj.ue_type == "cus":
            verify_attach = False
        try:
            if verify_attach:
                with self._verify_attach_messages(dut, rat, capture_device, analysis_list,
                                                  traffic_filters_json, ue_alias, ip_v4_or_6,
                                                  variables):
                    self.ue_ip_dict[ue_alias] = self._ue_attach(ue_obj, rat, device_id,
                                                                call_type, ue_alias, verify_teid)
            else:
                logger.info("Skipping Attach message verification")
                self.ue_ip_dict[ue_alias] = self._ue_attach(ue_obj, rat, device_id, call_type,
                                                            ue_alias, verify_teid)
            if not CallUtils.store.has_alias(ue_alias):
                CallUtils.store.add(ue_obj, alias=ue_alias)
        except IpNotFoundException as e:
            self.ip_exception_flag = 1
            raise e
        except TEIDNotGeneratedException as e:
            self.teid_exception_flag = 1
            raise e
        except Exception as e:
            logger.debug(traceback.format_exc())
            self.exception_flag = 1
            logger.error('Failure: {0}'.format(e))
            raise e

    def _ue_attach(self, ue_obj, rat, device_id, call_type, alias, verify_teid):
        logger.info("Attaching ue")
        ue_ip = ue_obj.attach(verify_teid, call_type)
        self._set_ue_ip_globally(ue_ip, rat, device_id)
        logger.info("Attach done")
        return ue_ip

    @contextmanager
    def _verify_attach_messages(self, dut, rat, capture_device, analysis_list,
                                traffic_filters_json, alias, ip_v4_or_6, variables):
        isexception = False
        self.perform_traffic_capture(capture_device=capture_device, alias=alias)
        try:
            yield
        except Exception as e:
            logger.debug(traceback.format_exc())
            isexception = True
            logger.error('failure: {0}'.format(e))
            raise e
        finally:
            capture_file = traffic_capture_stop(alias=alias)
        if not isexception:
            self._verify_pcap(rat, capture_file, analysis_list, traffic_filters_json,
                              ip_v4_or_6, variables)

    def perform_traffic_capture(self, capture_device, alias):
        """Perform traffic capture"""
        host_ip_str = self._build_capture_filter()
        traffic_capture_start(capture_device=capture_device, alias=alias,
                              capture_filter="(vlan and ({0})) or ({0})".format(host_ip_str[:-4]))

    def _build_capture_filter(self):
        admin_alias = _setup_oam_ops(alias=self.admin_alias)
        host_ip_str = ""
        for ip_type in [4, 6]:
            try:
                ip_mocs_dict = self.parameter_obj.get_parameter(
                    param_path="//IPADDRESSV{}_R-*:localIpAddrAllocated".format(ip_type), str_format=False, alias=admin_alias)
                for ip_moc in ip_mocs_dict:
                    ip = ip_mocs_dict[ip_moc]["localIpAddrAllocated"]
                    host_ip_str += "host {0} or ".format(ip)
            except Exception:
                pass
        else:
            if host_ip_str == "":
                raise Exception("Failed to build capture filter. Couldn't retrieve IPs needed "
                                "for the filter")
        logger.debug("Host ip string :: {}".format(host_ip_str))
        logger.debug("capture Filter: vlan and ({0}) or {0}".format(host_ip_str[:-4]))
        return host_ip_str

    def _verify_pcap(self, rat, capture_file, analysis_list, traffic_filters_json, ip_v4_or_6,
                     variables):
        if analysis_list is None:
            if rat == 'lte':
                if ip_v4_or_6.lower().strip() == 'ipv4':
                    analysis_list = ['lte_attach_request', 'lte_attach_accept',
                                     'lte_attach_complete']
                else:
                    analysis_list = ['lte_attach_request_v6', 'lte_attach_accept_v6',
                                     'lte_attach_complete_v6']
            elif rat == 'gsm':
                if ip_v4_or_6.lower().strip() == 'ipv4':
                    analysis_list = ['gsm_call_proceeding', 'gsm_connect_ack']
                else:
                    analysis_list = ['gsm_call_proceeding_v6', 'gsm_connect_ack_v6']
            elif rat == 'wcdma':
                if ip_v4_or_6.lower().strip() == 'ipv4':
                    analysis_list = ['wcdma_attach_request', 'wcdma_attach_response']
                else:
                    analysis_list = ['wcdma_attach_request_v6', 'wcdma_attach_response_v6']
        for analysis in analysis_list:
            analyse_pcap(pcap_filename=capture_file, analysis=analysis,
                         filter_file_name=traffic_filters_json,
                         admin_alias=self.admin_alias, variables=variables)

    def _create_ue_object(self, rat, device_id, dut=None, ip_v4_or_6='ipv4', **kwargs):
        """
            Creates instance of UE inherited class based on the given UE type
        Args:
            rat: The Radio Technology
            device_id: The UE device name according to testline config
            dut: The DUT where TEID verification has to happen

        Returns: UE object

        """
        ue_type = get_config_variable(['ue_devices', rat, device_id, "ue_type"])
        apn = get_config_variable(['ue_devices', rat, device_id, "apn"])

        ue_object = ()
        if ue_type.lower() == 'mobile':
            mobile_adb_id = get_config_variable(['ue_devices', rat, device_id, 'adb_id'])
            band = get_config_variable(['ue_devices', rat, device_id, 'band'])
            ue_object = Mobile(dut, device_id, rat, ue_type, mobile_adb_id, band, ip_v4_or_6)
        elif ue_type.lower() == 'dongle' or ue_type.lower() == 'module':
            iperf_remote_ip = get_config_variable(['iperf', self.iperf_device, 'ip'])
            interface_name = get_config_variable(['ue_devices', rat, device_id, 'interface'])
            if ue_type.lower() == 'dongle':
                macaddress = get_config_variable(['ue_devices', rat, device_id, 'macaddress'])
                dongle_id = get_config_variable(['ue_devices', rat, device_id, 'dongle_id'])
                if not interface_name:
                    raise Exception("Dongle network interface not specified in config")
                ue_object = Dongle(dut, macaddress, dongle_id, apn, interface_name,
                                   iperf_remote_ip, rat, device_id)
            else:
                ue_object = Module(dut, apn, iperf_remote_ip, rat, device_id, ip_v4_or_6)
        elif ue_type.lower() == 'iphy' or ue_type.lower() == 'airphone' or ue_type.lower() == 'cus':
            logger.info("Device id:{}".format(device_id))
            device_details = get_config_variable(['ue_devices', rat, device_id])
            logger.info("Device details: {}".format(device_details))
            if device_details is None:
                raise Exception("UE section {} doesnt exist in config file".format(device_id))
            if ue_type.lower() == 'iphy':
                ue_object = iphy(device_details, device_id, dut, rat, **kwargs)
            elif ue_type.lower() == 'cus':
                ue_object = CUS(device_details, device_id, dut, rat, **kwargs)
            else:
                airphone_variant = get_config_variable(['ue_devices', rat, device_id, 'variant'])
                if airphone_variant.lower() == 'sa':
                    ue_object = AirphoneSA(device_details, device_id, dut, rat, **kwargs)
                elif airphone_variant.lower() == 'nsa':
                    ue_object = AirphoneNSA(device_details, device_id, dut, rat, **kwargs)
        else:
            raise Exception('UE_Type {} Not Supported'.format(ue_type))
        return ue_object

    def _set_ue_ip_globally(self, ue_ip, rat, device_id):
        global_vars.ue_ip_dict['{}_{}_{}'.format(rat, 'ue_ip', device_id)] = ue_ip
        logger.debug('Global UE IP dictionary {}'.format(global_vars.ue_ip_dict))

    def _get_alias(self, rat, device_id, call_type):
        return '{}:{}:{}'.format(rat, device_id, call_type)

    def get_network_parameter(self, **kwargs):
        """Get network parameter"""
        if kwargs.get("lte"):
            rat, device_id = "lte", kwargs["lte"]
        else:
            rat, device_id = "wcdma", kwargs["wcdma"]
        ip_v4_or_6 = kwargs.get('ipv4_or_6', 'ipv4')
        return self._create_ue_object(rat, device_id, ip_v4_or_6=ip_v4_or_6)\
            .get_network_parameter()

    def configure_ue(self, **kwargs):
        """
            Allows the user to configure given UE device, by executing the given
            command and verifies
                :param kwargs: lte: value is deviceid:data or deviceid:voice
                :param kwargs: wcdma: value is deviceid:data or deviceid:voice
                :param kwargs: gsm: value is deviceid:data or deviceid:voice
        """
        ip_v4_or_6 = kwargs.pop('ipv4_or_6', 'ipv4')
        for rat, value, in list(kwargs.items()):
            if rat in get_config_variable(['rat_env']):
                device_id, call_type = value.split(':')
                alias = self._get_alias(rat, device_id, call_type)
                if CallUtils.store.has_alias(alias):
                    ue_obj = CallUtils.store.get(alias=alias)
                else:
                    ue_obj = self._create_ue_object(rat, device_id, ip_v4_or_6=ip_v4_or_6)
                output = ue_obj.configure_ue(**kwargs)
                expected_output = kwargs.get('expected_output', '')
                should_match = kwargs.get('should_match', True)
                if expected_output != '':
                    self._verify_output(should_match, output, expected_output)
                return output

    def _verify_output(self, should_match, output, expected_output):
        if should_match:
            if expected_output.lower().strip() != output.lower().strip():
                raise Exception('Output not expected. Expected {}, Found {}'.
                                format(expected_output, output))
            else:
                logger.info('Expected output found. Expected {}, Found {}'.
                            format(expected_output, output))
        else:
            if expected_output.lower().strip() == output.lower().strip():
                raise Exception('Output not expected. Expected {}, Found {}'.
                                format(expected_output, output))
            else:
                logger.info('Expected output found. Expected {}, Found {}'.
                            format(expected_output, output))

    def execute_cmd_on_egate(self, **kwargs):
        for rat, value, in list(kwargs.items()):
            if rat in get_config_variable(['rat_env']):
                device_id, call_type = value.split(':')
                alias = self._get_alias(rat, device_id, call_type)
                if CallUtils.store.has_alias(alias):
                    ue_obj = CallUtils.store.get(alias=alias)
                    return ue_obj.execute_cmd_on_egate(**kwargs)
                else:
                    raise Exception("Please Setup Call for CUS")


class CallUtilsFactory(object):
    """Call utils factory"""
    INSTANCE = None

    def __init__(self):
        pass

    @classmethod
    def get_instance(cls):
        """Get instance"""
        if not cls.INSTANCE:
            cls.INSTANCE = CallUtils()
        return cls.INSTANCE
